/* Requirement audit C3 / A5. All mutations are browser-memory demonstrations. */
const cpState={workView:matchMedia('(max-width:760px)').matches?'list':'board',noticeFilter:'all',policyTab:'授权',incidents:{'EI-17':'OPEN'},settings:{dedup:60},memory:'PENDING_REVIEW',logs:[],overrides:{},wizard:null,deliveries:{}};
const cpEsc=qaEsc;
const cpButton=(label,call,kind='')=>`<button type="button" class="btn ${kind}" onclick="${cpEsc(call)}">${label}</button>`;
const cpLink=(path,label)=>`<a class="btn" href="#/${path}">${label}</a>`;
const cpField=(label,id,value='',type='text')=>`<label class="stack small">${label}<input class="input" id="${id}" type="${type}" value="${cpEsc(value)}"></label>`;
const cpRead=id=>document.getElementById(id).value.trim();
const cpError=text=>{const el=document.getElementById('cp-error');if(el)el.textContent=text;else toast(text);};
const cpDemo='<div class="note info">浏览器内存演示；刷新恢复样例。模拟重新认证不构成真实身份认证。</div>';
function cpModal(title,body,action){openModal(`<div class="modal-h"><h3>${title}</h3></div><div class="modal-b stack">${body}<div id="cp-error" role="alert" class="small" style="color:var(--danger)"></div></div><div class="modal-f">${cpButton('取消','closeModal()')}${action}</div>`);}
function cpWrap(key,links){const old=PAGES[key];PAGES[key]=arg=>old(arg)+`<div class="row wrap" style="margin-top:20px">${links(arg)}</div>`;}
cpWrap('knowledge',()=>cpLink('knowledge-settings','知识设置')+cpLink('memory-review','记忆待审队列'));
cpWrap('overview',()=>cpLink('metrics','指标')+cpLink('notifications','通知中心')+cpLink('my-worklog','个人工时填报'));
cpWrap('settings',()=>cpLink('notifications','通知中心')+cpLink('my-worklog','个人工时填报'));
cpWrap('test-cases',arg=>cpLink('test-plan/'+(arg||CURPROJ||'p1'),'测试计划详情'));
cpWrap('previews',arg=>VIEWER==='team'?cpLink('preview-share/'+(arg||CURPROJ||'p1'),'预览分享 · v1.1'):'');
const cpWorkPage=PAGES.work;
PAGES.work=arg=>{const pid=arg||CURPROJ||'p1',list=WI.filter(w=>w.p===pid);return `<div class="row wrap">${['board','list'].map(v=>cpButton(v==='board'?'看板视图':'列表视图',`cpState.workView='${v}';route()`,cpState.workView===v?'primary':'')).join('')}</div>`+(cpState.workView==='board'?cpWorkPage(pid):head(projectName(pid),'任务列表','同一项目工作项，切换视图不会改变项目。')+card('工作项',cpPaged('tasks', ['编号 / 标题','状态','负责人','完成阶梯'],list.map(w=>[`<a href="#/workitem/${w.id}">${w.id} · ${cpEsc(w.t)}</a>`,S(w.s),who(w.who),ladder(w.l)]))))};
PAGES.metrics=arg=>{const pid=arg||CURPROJ||'p1',list=WI.filter(w=>w.p===pid),accepted=list.filter(w=>w.l>=3).length;return head('目标与报告','指标','示例口径；内部轮次和返工成本计入交付成本。')+card('统计范围',`<p>${projectName(pid)} · 2026-10 · 浏览器样例，非生产统计</p>`)+card('分层指标',qaTable(['指标','L2 独立验证','L3 团队接受','口径'],[['当前工作项数',list.filter(w=>w.l>=2).length,accepted,'同一项目，按工作项去重'],['首次验收率','8 / 10 = 80%','7 / 10 = 70%','分母为首次进入对应验证 / 裁决的工作项'],['内部轮次数','18','18','含失败与返工轮次'],['每个已接受交付物成本','不适用','$42 / 7 = $6','执行、内部验证及返工费用全部计入'],['穿透率','2 / 10 = 20%','1 / 7 = 14.3%','内部通过后被下一层拒绝的比例']]))};
PAGES.notifications=()=>{const list=NOTICES.map((n,i)=>({...n,index:i})).filter(n=>cpState.noticeFilter!=='unread'||!n.read);return head('个人','通知中心','站内通知独立于免打扰设置；点击对象会标记已读。',cpButton('全部标为已读','NOTICES.forEach(n=>n.read=true);route()'))+`<div class="row">${cpButton('全部',"cpState.noticeFilter='all';route()")}${cpButton('未读',"cpState.noticeFilter='unread';route()")}${cpLink('settings','通知设置')}</div>`+card('通知',list.map(n=>`<div class="inbox-item"><div class="grow"><b>${cpEsc(n.t)}</b><div class="muted xs">${n.at} · ${n.read?'已读':'未读'}</div></div>${cpButton('查看',`cpOpenNotice(${n.index})`)}</div>`).join('')||'<div class="empty">没有未读通知。</div>')};
function cpOpenNotice(i){const n=NOTICES[i];n.read=true;if(n.pre&&n.pre.includes('BIL-142'))WITAB['BIL-142']=5;go(n.go);}
const cpPolicy=PAGES.policy;
PAGES.policy=()=>`<div class="row wrap">${['授权','升级事件','设置'].map(t=>cpButton(t,`cpState.policyTab='${t}';route()`,cpState.policyTab===t?'primary':'')).join('')}</div>`+(cpState.policyTab==='授权'?cpPolicy():cpState.policyTab==='升级事件'?head('治理','升级事件','操作与事实分离；恢复项目需在项目页面处理。')+card('事件',qaTable(['严重度 / 规则','项目 / 主体','状态 / 次数','动作执行结果','操作'],[['HIGH · 预算 96.8%','商户控制台 · D-17',cpState.incidents['EI-17']+' · 2','委托冻结成功；项目保持',''+cpButton('查看事实',"cpIncident()")+cpButton('确认',"cpAckIncident()")]])):head('治理','策略设置','可配置升级去重窗口；此表单不授予新权限。')+card('事件设置',cpField('去重窗口（秒，1–3600）','cp-dedup',cpState.settings.dedup,'number')+cpButton('保存',"cpSavePolicy()",'primary')));
function cpIncident(){cpModal('EI-17 事实与时间线','<dl class="kv"><dt>事实</dt><dd>预算 $48.40 / $50；阈值 95%</dd><dt>权限来源</dt><dd>SYSTEM:escalation</dd><dt>动作</dt><dd>D-17 已冻结；项目 hold 成功</dd><dt>时间线</dt><dd>08:12 触发 → 08:12 冻结 → 待人工处理</dd></dl>'+cpLink('project/p2','在所属项目处置'),cpButton('关闭','closeModal()'));}
function cpAckIncident(){if(cpState.incidents['EI-17']!=='OPEN')return toast('事件已确认');cpState.incidents['EI-17']='ACK';cpState.logs.push({action:'escalation.acknowledged',object:'EI-17',actor:'morgan'});route();}
function cpSavePolicy(){const n=Number(cpRead('cp-dedup'));if(!Number.isInteger(n)||n<1||n>3600)return toast('窗口必须为 1–3600 的整数');cpState.settings.dedup=n;toast('策略设置已保存（演示）');}
PAGES['knowledge-settings']=()=>head('知识库','知识设置','复用现有 PostgreSQL K1；K2 为可选模块。')+card('检索后端',qaKV([['方言','PostgreSQL'],['K1 全文','已启用'],['MySQL ngram / SQLite FTS5','不适用当前方言'],['K2 混合检索','模块未启用'],['启用条件','向量扩展、兼容 embedding 模型、维度与 API 凭据']]))+card('检索参数',cpField('候选上限（1–200）','cp-top',cpState.settings.top||50,'number')+cpButton('保存参数','cpSaveKnowledge()','primary'));
function cpSaveKnowledge(){const n=Number(cpRead('cp-top'));if(!Number.isInteger(n)||n<1||n>200)return toast('候选上限必须为 1–200 的整数');cpState.settings.top=n;toast('知识设置已保存（演示）');}
PAGES['memory-review']=()=>head('知识库','记忆待审队列','只有非写入者的人类批准规则；记忆不替代事实。')+card('规则 MR-12',qaKV([['内容','CSV 导出采用 UTF-8 BOM'],['写入者','Ada'],['范围','账单中心'],['状态',cpState.memory],['来源','BIL-139 裁决反馈'],['风险','格式规则，可能不适用于其他客户端']])+cpLink('workitem/BIL-139','查看来源')+(cpState.memory==='PENDING_REVIEW'?cpButton('批准',"cpMemoryDecision('APPROVED')",'primary')+cpButton('驳回',"cpMemoryDecision('REJECTED')",'danger'):''));
function cpMemoryDecision(result){cpModal(result==='APPROVED'?'批准规则记忆':'驳回规则记忆',cpField('审核理由（必填）','cp-reason'),cpButton('记录审核',`cpMemorySave('${result}')`,'primary'));}
function cpMemorySave(result){const reason=cpRead('cp-reason');if(!reason)return cpError('请填写审核理由');if(cpState.memory!=='PENDING_REVIEW')return cpError('这条记忆已处理');cpState.memory=result;cpState.logs.push({action:'memory.'+result.toLowerCase(),actor:'morgan',writer:'ada',reason});closeModal();route();}
PAGES['test-plan']=arg=>{const pid=arg||CURPROJ||'p1';return head(projectName(pid),'测试计划详情','TP-'+pid+' · 冻结验收版本；执行者只读隐藏测试。')+card('范围与门禁',qaKV([['所属项目',projectName(pid)],['状态','已冻结'],['需求版本',pid==='p1'?'R-12 v4':'该项目独立测试范围'],['环境','隔离验收副本'],['隐藏测试','只展示数量与哈希，不展示内容']]))+card('覆盖工作项',cpPaged('test-plan', ['工作项','验证方式','结果'],WI.filter(w=>w.p===pid).map(w=>[`<a href="#/workitem/${w.id}">${w.id} · ${cpEsc(w.t)}</a>`,'测试 / 命令 / 人工验证',w.l>=2?'已有独立验证':'待执行'])))+cpLink('test-cases/'+pid,'返回用例与测试计划')};
PAGES['preview-share']=arg=>{const pid=arg||CURPROJ||'p1';return head(projectName(pid),'预览分享查看页','只读脱敏快照，与正式交付和甲方验收分离。','<span class="badge b-stale">v1.1</span>')+card('共享配置',cpDemo+qaKV([['项目',projectName(pid)],['访问范围','当前项目邀请成员；不开放匿名跨项目访问'],['分享状态',cpState.settings['share-'+pid]?'已撤销':'有效（样例）'],['到期','2026-10-19'],['披露','仅公开预览；不含内部测试、密钥、机器日志']])+cpLink('previews/'+pid,'查看本项目预览')+cpButton('撤销分享',`cpState.settings['share-${pid}']=true;route()`,'danger'))};
PAGES['my-worklog']=()=>{
  const pid=CURPROJ||'p1',actor=yxState.actor,records=yxState.worklogs.filter(log=>log.actor===actor&&WI.some(w=>w.id===log.wi&&w.p===pid));
  return head('个人','个人工时填报','与项目工时共用记录；只记录当前演示身份本人的投入，不能自批。','<span class="badge b-stale">v1.1</span>')+yxActor()+card('填报',`<form onsubmit="event.preventDefault();cpWorklogSave()"><div class="stack"><p>当前项目：${cpEsc(projectName(pid))} · 填报人：${cpEsc(PEOPLE[actor].n)}</p><label>关联工作项<select id="cp-log-work" class="select">${WI.filter(w=>w.p===pid).map(w=>`<option value="${w.id}">${w.id} · ${cpEsc(w.t)}</option>`).join('')}</select></label>${cpField('日期','cp-log-date','2026-10-12','date')}<label class="stack small">时长（小时，0.25–24，按15分钟）<input class="input" id="cp-log-hours" type="number" step="0.25" min="0.25" max="24" required></label>${cpField('工作说明（必填，最多500字）','cp-log-note')}<button class="btn primary" type="submit" ${yxIsHuman()?'':'disabled'}>提交审批</button>${yxIsHuman()?'':'<p class="muted small">Agent运行时长由系统事实记录，不能登记人工工时。</p>'}<div id="cp-error" role="alert"></div></div></form>`)+card('我的记录',qaTable(['工作项','日期','时长','说明','状态'],records.map(log=>[log.wi,log.date,(log.minutes/60)+' 小时',cpEsc(log.note),cpEsc(log.state)])))+cpLink('worklog/'+pid,'查看项目工时与审批');
};
function cpWorklogSave(){
  if(VIEWER!=='team'||!yxIsHuman())return cpError('仅人类可登记本人工时');
  const hours=Number(cpRead('cp-log-hours')),minutes=hours*60,note=cpRead('cp-log-note'),date=cpRead('cp-log-date'),actor=yxState.actor;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date||!note||note.length>500||!Number.isFinite(hours)||hours<.25||hours>24||!Number.isInteger(minutes)||minutes%15!==0)return cpError('填写有效日期、最多500字说明和0.25–24小时（按15分钟）');
  const work=cpRead('cp-log-work');if(!WI.some(w=>w.id===work&&w.p===(CURPROJ||'p1')))return cpError('工作项不属于当前项目');
  const total=yxState.worklogs.filter(log=>log.actor===actor&&log.date===date).reduce((sum,log)=>sum+log.minutes,0);
  if(total+minutes>1440)return cpError('你在该日期的总时长将超过1440分钟');
  const record={id:'WL-'+(24+yxState.worklogs.length),wi:work,actor,category:'执行',date,minutes,note,state:'待审批',cost:0};
  yxState.worklogs.push(record);cpState.logs.push({action:'worklog.submitted',object:record.id,actor,work,date,hours,note});route();toast('已提交项目工时审批；本人不能自批');
}
const cpInboxKinds=[['WORK_ITEM_REVIEW','工作项评审','workitem/BIL-142'],['INTERACTION','运行时交互','execution/EX-9102'],['HUMAN_VERIFICATION','人工验证','execution/EX-9102'],['CLARIFICATION_REPLY','澄清回复','changes/p1'],['DELIVERY_CONFIRM','交付确认','deliveries/p1'],['ESCALATION_ALERT','升级告警','policy'],['MEMORY_RULE_APPROVAL','规则记忆审批','memory-review'],['DISPATCH_PROPOSAL','派单提案','dispatch/p1'],['INTAKE_TRIAGE','来件分诊','changes/p1'],['EXECUTION_ATTENTION','执行关注','execution/EX-9102'],['ENSEMBLE_APPROVAL','集成计划批准','heavy/BIL-142'],['ENSEMBLE_SELECTION','多执行择优','heavy/BIL-142'],['AGENT_SPAWN_APPROVAL','Agent 创建审批','members'],['PLAN_CONFIRMATION','计划确认','plans'],['REPORT_CONFIRMATION','报告确认','reports'],['REPORT_BLOCKED','报告阻断','reports'],['REPORT_OVERDUE','报告逾期','reports'],['ESCALATION_INTERNAL_EXHAUSTED','内部轮次耗尽','workitem/BIL-142'],['REQUIREMENT_CONFLICT','需求冲突','requirement/R-12'],['ANDON','停线处置','workitem/BIL-145'],['EXCEPTION_DECISION','例外裁决','exception/BIL-142'],['PLAN_APPROVAL','执行计划审批','workitem/BIL-142'],['QUALITY_ESCAPE','质量穿透','escapes/p1'],['REVIEW_SHEET','需求评审单','review-sheet'],['WORKLOG_APPROVAL','工时审批','worklog/p1'],['AGENT_STATUS_ATTENTION','Agent 状态关注','agent/ada']];
cpWrap('inbox',()=>card('完整裁决类型目录（含后续追加）','<p class="muted small">这是类型目录，不制造待办。实际处理在对象页面完成；不提供批量通过。</p>'+cpPaged('decision-kinds', ['类型','说明','处理入口'],cpInboxKinds.map(([kind,label,path])=>[kind,label+(kind.startsWith('ENSEMBLE')?' <span class="badge b-stale">v1.1</span>':''),cpLink(path,'打开对象')]))));
const cpDeliveryPage=PAGES.delivery;
PAGES.delivery=id=>{const d=exDeliveries[id||'D-1'];return cpDeliveryPage(id)+(d&&d.state==='DRAFT'?cpLink('delivery-editor/'+(id||'D-1'),'编辑交付包'):'')+(d?card('人工覆盖披露',d.items.filter(w=>cpState.overrides[w]).map(w=>`<p>${w}：自动结论 ${cpState.overrides[w].original}；人工覆盖理由：${cpEsc(cpState.overrides[w].reason)} · Morgan · 模拟重新认证</p>`).join('')||'<p class="muted small">没有人工覆盖记录。</p>'):'');};
function cpDeliveryContacts(pid){const p=pjProject(pid);if(!p||!p.contacts)return [];return [{id:pid+'-primary',name:pid==='p1'?'Lee · Contoso':p.client,project:pid}];}
function cpDeliveryChannels(pid){return Object.entries(exChannels).filter(([,c])=>c.project===pid&&c.enabled).map(([key])=>({key,name:({portal:'门户',email:'邮件',api:'API'})[key]}));}
function cpDeliveryWork(id){return pjWork.find(w=>w.id===id);}
function cpDeliveryItemError(id,deliveryId){const d=exDeliveries[deliveryId],w=cpDeliveryWork(id);if(!d||!w||w.p!==d.project)return '工作项不属于本项目';if(w.s!=='ACCEPTED'||w.l!==3)return '需已接受 ACCEPTED / L3';const req=pjRequirements.find(r=>r.id===w.requirement&&r.p===w.p);if(w.stale||!req||w.baseline!=='v'+req.version)return '需求基线缺失、已过期或版本不一致';if(Object.entries(exDeliveries).some(([key,other])=>key!==deliveryId&&['READY','SENT'].includes(other.state)&&other.items.includes(id)))return '已被其他在途交付占用';const fact=cpVerificationSnapshot(id),override=cpState.overrides[id];if(!fact.execution||!lsRunFacts[id])return '缺少独立验证与证据来源记录';const execution=exExecutions[fact.execution];if(!execution||execution.wi!==id)return '验证证据不属于当前工作项';if(fact.original==='PASSED'&&execution.state==='SUCCEEDED')return '';if(override&&override.sourceVersion===fact.sourceVersion&&['FAILED','INCONCLUSIVE'].includes(fact.original))return '';return '独立验证未通过且没有针对当前记录的人工覆盖';}
function cpEligible(w,id){return !!w?.id&&!cpDeliveryItemError(w.id,id);}
function cpDeliveryGuard(id){const d=exDeliveries[id];if(VIEWER!=='team'||!d||d.state!=='DRAFT')return '交付不在可编辑草稿状态';if(!d.title?.trim()||!d.notes?.trim()||!d.items?.length)return '填写标题、发布说明并选择工作项';if(!cpDeliveryContacts(d.project).some(c=>c.id===d.contactId))return '请选择本项目当前可签收联系人';if(!cpDeliveryChannels(d.project).some(c=>c.key===d.channelKey))return '请选择本项目当前有效交付渠道';return d.items.map(item=>{const error=cpDeliveryItemError(item,id);return error?item+'：'+error:'';}).find(Boolean)||'';}
function cpDeliveryFingerprint(id){const d=exDeliveries[id];return JSON.stringify([d.title,d.notes,d.contactId,d.channelKey,d.items.map(item=>{const w=cpDeliveryWork(item),fact=cpVerificationSnapshot(item);return [item,w?.s,w?.l,w?.baseline,w?.stale,fact.sourceVersion,cpState.overrides[item]?.sourceVersion];})]);}
PAGES['delivery-editor']=id=>{const d=exDeliveries[id];if(!d)return head('交付','交付包不存在','');if(d.state!=='DRAFT')return head('交付','交付包只读','只有草稿可编辑。')+cpLink('delivery/'+id,'返回详情');const contacts=cpDeliveryContacts(d.project),channels=cpDeliveryChannels(d.project);return head(projectName(d.project),'交付包编辑器','构建和确认共同复核联系人、渠道、最新基线、独立验证事实及在途占用。')+card('草稿内容',cpField('标题','cp-delivery-title',d.title)+`<label class="stack">发布说明（必填）<textarea id="cp-delivery-notes" class="input">${cpEsc(d.notes||'')}</textarea></label><label class="stack">可签收联系人（必选）<select id="cp-delivery-contact" class="select"><option value="">请选择同项目联系人</option>${contacts.map(c=>`<option value="${c.id}" ${d.contactId===c.id?'selected':''}>${cpEsc(c.name)}</option>`).join('')}</select></label><label class="stack">交付渠道（必选）<select id="cp-delivery-channel" class="select"><option value="">请选择有效渠道</option>${channels.map(c=>`<option value="${c.key}" ${d.channelKey===c.key?'selected':''}>${c.name}</option>`).join('')}</select></label>${!contacts.length?'<p class="note warn">本项目没有可签收联系人，请先在项目设置中配置。</p>':''}${!channels.length?'<p class="note warn">本项目尚无有效交付渠道，请先配置项目需求开口。</p>':''}`+qaTable(['选择','工作项','资格检查','覆盖标注'],pjWork.filter(w=>w.p===d.project).map(w=>{const error=cpDeliveryItemError(w.id,id);return [`<input name="cp-delivery-item" type="checkbox" value="${w.id}" ${d.items.includes(w.id)?'checked':''} ${error?'disabled':''} aria-label="选择 ${w.id}">`,w.id+' · '+cpEsc(w.t),error||'当前基线、独立验证与团队接受已满足',cpState.overrides[w.id]?'人工覆盖，交付必须披露':'无'];}))+`<div id="cp-error" role="alert"></div><div class="row">${cpButton('保存草稿',`cpDeliverySave('${id}',false)`)}${cpButton('构建检查并提交确认',`cpDeliverySave('${id}',true)`,'primary')}</div>`)+cpLink('delivery/'+id,'返回交付详情');};
function cpDeliverySave(id,build){const d=exDeliveries[id];if(VIEWER!=='team'||!d||d.state!=='DRAFT')return cpError('交付已不在草稿状态');const items=[...document.querySelectorAll('input[name="cp-delivery-item"]:checked')].map(el=>el.value),title=cpRead('cp-delivery-title'),notes=cpRead('cp-delivery-notes'),contactId=cpRead('cp-delivery-contact'),channelKey=cpRead('cp-delivery-channel');if(!title||!notes||!items.length)return cpError('填写标题、发布说明并选择工作项');if(items.some(item=>cpDeliveryWork(item)?.p!==d.project))return cpError('不能加入其他项目的工作项');Object.assign(d,{title,notes,items,count:items.length,contactId,channelKey,contact:cpDeliveryContacts(d.project).find(c=>c.id===contactId)?.name||'待选择可签收联系人',channel:cpDeliveryChannels(d.project).find(c=>c.key===channelKey)?.name||'待选择渠道',buildChecked:false});if(build){const error=cpDeliveryGuard(id);if(error)return cpError(error);d.buildChecked=true;d.buildFingerprint=cpDeliveryFingerprint(id);cpState.logs.push({action:'delivery.confirmation_requested',object:id,actor:'morgan'});toast('模拟构建检查通过；使用已有验证事实，没有生成新的运行证据');}else toast('交付草稿已保存（演示）');}
const cpManifest=exManifest;
exManifest=function(){const result=cpManifest(),delivery=exDeliveries[exCurrentDelivery];if(delivery.buildFingerprint){result.items=delivery.items.map(id=>{const w=cpDeliveryWork(id),fact=cpVerificationSnapshot(id);return {key:id,title:w.t,baseline:w.baseline,accepted_by:'团队',evidence:[{id:fact.execution,type:'EXECUTION_REFERENCE',producer:exExecutions[fact.execution]?.actor,verification:{result:fact.original,source:'现有内部阶段样例记录',stages:[...lsRunFacts[id].stages],demo:true}}]};});result.generated_at=null;result.excluded_files=[];result.limitations=['仅引用已有样例记录；没有生成实际证据包、文件哈希或新的测试报告'];}result.items.forEach(item=>{if(cpState.overrides[item.key])item.human_override=cpState.overrides[item.key];});return result;};
cpWrap('workitem',id=>{const w=WI.find(w=>w.id===id);return w?cpLink('verification-override/'+id,'人工覆盖自动结论')+(cpState.overrides[id]?card('人工覆盖标注',`自动结论保持 ${cpState.overrides[id].original}；裁决：人工覆盖。理由：${cpEsc(cpState.overrides[id].reason)}；在交付清单中披露。`):''):'';});
function cpVerificationSnapshot(id){
  const fact=lsRunFacts[id],stages=fact?.stages?.slice(0,4)||[];
  const original=!stages.length?'NOT_RUN':stages.includes('失败')?'FAILED':stages.includes('无法判定')?'INCONCLUSIVE':stages.every(s=>['通过','跳过'].includes(s))?'PASSED':'PENDING';
  return {original,execution:fact?.execution||null,round:fact?.round||0,sourceVersion:JSON.stringify([fact?.execution,fact?.round,stages])};
}
PAGES['verification-override']=id=>{const w=WI.find(w=>w.id===id);if(!w)return head('验证','工作项不存在','');const fact=cpVerificationSnapshot(id),allowed=['FAILED','INCONCLUSIVE'].includes(fact.original)&&cpState.overrides[id]?.sourceVersion!==fact.sourceVersion;return head(projectName(w.p),'人工覆盖自动结论','读取当前验证记录；原自动结果保持只读，人工覆盖不自动完成 L3 接受。')+card('结论与权限',qaKV([['工作项',id],['裁决人','Morgan · 人类交付负责人'],['权限来源','ROLE:delivery_lead'],['自动结论',fact.original],['验证来源',(fact.execution||'无执行记录')+' · 内部第 '+fact.round+' 轮']])+cpDemo+cpField('覆盖理由（必填）','cp-override-reason')+`<label class="row"><input id="cp-override-auth" type="checkbox">我已完成模拟重新认证（仅演示）</label><div id="cp-error" role="alert"></div><button type="button" class="btn danger" ${allowed?'':'disabled'} onclick="cpOverrideSave('${id}')">记录人工覆盖</button>${allowed?'':'<p class="muted small">当前结果不能覆盖，或同一验证记录已经裁决；只有 FAILED / INCONCLUSIVE 可处理。</p>'}`)+card('审计记录',qaTable(['动作','原结论','理由','认证'],cpState.logs.filter(l=>l.object===id&&l.action==='verification.force_valid').map(l=>[l.action,l.original,cpEsc(l.reason),'模拟，非真实认证'])));};
function cpOverrideSave(id){if(VIEWER!=='team')return cpError('甲方不具有团队裁决权限');const fact=cpVerificationSnapshot(id);if(!WI.some(w=>w.id===id)||!['FAILED','INCONCLUSIVE'].includes(fact.original)||cpState.overrides[id]?.sourceVersion===fact.sourceVersion)return cpError('验证结果不可覆盖或本次验证已裁决，请重新查看');const reason=cpRead('cp-override-reason');if(!reason)return cpError('覆盖理由必填');if(!document.getElementById('cp-override-auth').checked)return cpError('请完成模拟重新认证');const record={action:'verification.force_valid',object:id,...fact,reason,actor:'morgan',authority:'ROLE:delivery_lead',reauthentication:'SIMULATED_ONLY',time:new Date().toISOString()};cpState.overrides[id]=record;cpState.logs.push(record);route();toast('人工覆盖已记录；自动结论保持原值，交付标注已同步');}
const cpAudit=PAGES.audit;
PAGES.audit=()=>cpAudit()+card('本次模拟追加审计',qaTable(['动作','对象','主体','理由'],cpState.logs.map(l=>[cpEsc(l.action),cpEsc(l.object||l.work||'MR-12'),l.actor,cpEsc(l.reason||l.note||'')])));
function cpAgentWizard(kind,id){closeDrawer();cpState.wizard={kind,id,step:0,name:kind==='retire'?PEOPLE[id].n:'',role:'执行者',reason:'',project:CURPROJ||'p1',force:false};cpWizardRender();}
newAgent=()=>cpAgentWizard('create');retire=id=>cpAgentWizard('retire',id);
function cpWizardCapture(){const w=cpState.wizard;for(const key of ['name','role','reason','project','confirm']){const el=document.getElementById('cp-wizard-'+key);if(el)w[key]=el.value.trim();}const force=document.getElementById('cp-wizard-force');if(force)w.force=force.checked;}
function cpWizardRender(){const w=cpState.wizard,create=w.kind==='create';let body=`<div class="row">${[create?'身份与职责':'退役影响',create?'范围与负责人':'交接与方式','确认'].map((t,i)=>`<span class="chip ${w.step===i?'on':''}">${i+1}. ${t}</span>`).join('')}</div>`;if(w.step===0)body+=create?cpField('名称（必填）','cp-wizard-name',w.name)+`<label>职责<select id="cp-wizard-role" class="select">${['执行者','协调员','评审者'].map(r=>`<option ${w.role===r?'selected':''}>${r}</option>`).join('')}</select></label>`:qaKV([['Agent',cpEsc(w.name)],['影响','停止新分派；未完工作需转派；历史证据与审计保留'],['凭证','退役完成后吊销（原型不会操作真实凭证）']]);if(w.step===1)body+=create?`<label>项目范围<select id="cp-wizard-project" class="select">${PROJECTS.map(p=>`<option value="${p.id}" ${p.id===w.project?'selected':''}>${cpEsc(p.name)}</option>`).join('')}</select></label><p>负责人类：Morgan；创建来源：人类创建。默认无额外裁决授权。</p>`:cpField('交接说明 / 退役理由（必填）','cp-wizard-reason',w.reason)+`<label class="row"><input id="cp-wizard-force" type="checkbox" ${w.force?'checked':''}>强制退役（机器异常，可能丢失未提交状态）</label>`;if(w.step===2)body+=qaKV([['操作',create?'创建 '+cpEsc(w.name):'退役 '+cpEsc(w.name)],['范围',create?projectName(w.project):cpEsc(w.reason)],['方式',create?w.role:w.force?'强制':'正常交接']])+cpDemo+(create?'':cpField('输入 Agent 名称确认','cp-wizard-confirm',w.confirm||''))+`<label class="row"><input id="cp-wizard-auth" type="checkbox">已完成模拟重新认证（仅演示）</label>`;cpModal(create?'新建 Agent 向导':'退役向导',body,(w.step?cpButton('上一步','cpWizardMove(-1)'):'')+cpButton(w.step===2?'确认模拟操作':'下一步','cpWizardMove(1)','primary'));}
function cpWizardMove(delta){const w=cpState.wizard;cpWizardCapture();if(delta<0){w.step--;return cpWizardRender();}if(w.kind==='create'&&w.step===0&&(!w.name||Object.values(PEOPLE).some(p=>p.n===w.name)))return cpError('填写不重复的 Agent 名称');if(w.kind==='retire'&&w.step===1&&!w.reason)return cpError('填写交接说明与退役理由');if(w.step<2){w.step++;return cpWizardRender();}if(!document.getElementById('cp-wizard-auth').checked)return cpError('请完成模拟重新认证');if(w.kind==='retire'&&w.confirm!==w.name)return cpError('名称不匹配');if(w.kind==='create'){const id='demo'+Date.now();PEOPLE[id]={n:w.name,k:'a',origin:'human',owner:'morgan',role:w.role,c:'#64748b',a:w.name.slice(0,2)};MEMBERS.push([id,'Agent',w.role,'Morgan',projectName(w.project),'待配置','—','STOPPED']);}else{const member=MEMBERS.find(m=>m[0]===w.id);if(member)member[7]='RETIRED';PEOPLE[w.id].retired=true;}cpState.logs.push({action:w.kind==='create'?'agent.created':'agent.retired',object:w.id||w.name,actor:'morgan',reason:w.reason||'人类创建',reauthentication:'SIMULATED_ONLY'});closeModal();go('members');toast('模拟操作完成；真实 Agent 和凭证未改变');}
[['metrics','指标','goals'],['notifications','通知中心','overview'],['knowledge-settings','知识设置','knowledge'],['memory-review','记忆待审','knowledge'],['my-worklog','个人工时','settings'],['test-plan','测试计划详情','test-cases'],['preview-share','预览分享','previews'],['delivery-editor','交付包编辑器','deliveries'],['verification-override','人工覆盖','work']].forEach(([key,title,parent])=>{TITLES[key]=title;NAVPARENT[key]=parent;});
['metrics','test-plan','preview-share','delivery-editor','verification-override'].forEach(key=>PROJECT_ROUTES.add(key));
const cpOwnerProject=ownerProject;
ownerProject=function(key,arg){if(key==='delivery-editor')return exDeliveries[arg]?.project;if(key==='verification-override')return WI.find(w=>w.id===arg)?.p;return cpOwnerProject(key,arg);};
/* Keep notifications inside the viewer's projection, including the bell denominator. */
function cpVisibleNotices(){return NOTICES.map((n,index)=>({...n,index})).filter(n=>VIEWER!=='client'||n.clientVisible===true);}
openNotices=function(e){const list=cpVisibleNotices(),m=document.getElementById('noticeMenu');m.innerHTML=`<small>通知 · ${list.filter(n=>!n.read).length} 条未读</small>`+list.map(n=>`<button onclick="document.getElementById('noticeMenu').classList.remove('open');cpOpenNotice(${n.index})"><span style="white-space:normal;text-align:left">${cpEsc(n.t)}<span class="muted xs"> · ${n.read?'已读':'未读'}</span></span></button>`).join('')+(list.length?'':'<div class="empty">没有可见通知。</div>')+`<div class="row">${VIEWER==='team'?cpLink('notifications','通知中心'):''}${cpLink('settings','通知设置')}</div>`;icons();toggleMenu(e,'noticeMenu');};
const cpRenderSide=renderSide;
renderSide=function(cur,arg){cpRenderSide(cur,arg);document.getElementById('bellDot').textContent=cpVisibleNotices().filter(n=>!n.read).length||'';};
cpInboxKinds.pop();cpInboxKinds.push(['PREVIEW_SHARE_APPROVAL','预览分享审批','preview-share/p1']);
/* Bound DOM rendering to 20 rows. Real implementation must apply permission filters
   and cursor pagination on the server; this is only in-memory UI behavior. */
cpState.tables={};
function cpPaged(key,heads,rows){const state=cpState.tables[key]||{query:'',page:0},filtered=rows.filter(row=>row.join(' ').replace(/<[^>]*>/g,'').toLowerCase().includes(state.query.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/20));state.page=Math.min(state.page,pages-1);cpState.tables[key]=state;return `<div class="row wrap"><label>筛选 <input class="input" value="${cpEsc(state.query)}" aria-label="筛选 ${key}" onchange="cpTableQuery('${key}',this.value)"></label><span class="muted small">${filtered.length} 条 · 每页最多 20 条</span></div>`+qaTable(heads,filtered.slice(state.page*20,state.page*20+20))+`<div class="row wrap" style="margin-top:12px">${cpButton('上一页',`cpTablePage('${key}',-1)`)}<span>第 ${state.page+1} / ${pages} 页</span>${cpButton('下一页',`cpTablePage('${key}',1)`)}</div>`+(filtered.length?'':'<div class="empty">没有匹配记录，清空筛选后重试。</div>');}
function cpTableQuery(key,query){cpState.tables[key]={query,page:0};route();}
function cpTablePage(key,delta){const state=cpState.tables[key];state.page=Math.max(0,state.page+delta);route();}
const cpWizardAdvance=cpWizardMove;
cpWizardMove=function(delta){cpWizardCapture();if(delta>0&&cpState.wizard.kind==='create'&&/[<>"'&]/.test(cpState.wizard.name))return cpError('名称不能包含 HTML 或引号字符');cpWizardAdvance(delta);};


function cpConfirmDelivery(id){const d=exDeliveries[id];if(!d||d.state!=='DRAFT'||!d.buildChecked)return toast('请先完成草稿构建检查');cpModal('交付包人工确认',cpDemo+cpField('确认理由（必填）','cp-delivery-confirm-reason')+'<label class="row"><input id="cp-delivery-confirm-auth" type="checkbox">完成模拟重新认证（仅演示）</label>',cpButton('确认待发送',`cpConfirmDeliverySave('${id}')`,'primary'));}
function cpConfirmDeliverySave(id){const d=exDeliveries[id],reason=cpRead('cp-delivery-confirm-reason');if(!reason)return cpError('确认理由必填');if(!document.getElementById('cp-delivery-confirm-auth').checked)return cpError('请完成模拟重新认证');if(cpDeliveryGuard(id)||!d.buildChecked||d.buildFingerprint!==cpDeliveryFingerprint(id))return cpError('构建或工作项状态已变化，重新检查');d.state='READY';cpState.logs.push({action:'delivery.ready',object:id,actor:'morgan',reason,reauthentication:'SIMULATED_ONLY'});closeModal();go('delivery/'+id);toast('已确认待发送（模拟）；没有真实发送通知');}
const cpEditor=PAGES['delivery-editor'];
PAGES['delivery-editor']=id=>cpEditor(id)+(exDeliveries[id]?.state==='DRAFT'&&exDeliveries[id].buildChecked?cpButton('人工确认待发送',`cpConfirmDelivery('${id}')`,'primary'):'');
const cpSharePage=PAGES['preview-share'];
PAGES['preview-share']=arg=>{const pid=arg||CURPROJ||'p1';return cpState.settings['share-'+pid]?head(projectName(pid),'分享已撤销','此分享入口不再提供预览内容。','<span class="badge b-stale">v1.1</span>'):cpSharePage(arg);};
const cpSaveDraft=cpDeliverySave;
cpDeliverySave=function(id,build){if(!build&&exDeliveries[id])exDeliveries[id].buildChecked=false;cpSaveDraft(id,build);if(build&&exDeliveries[id]?.buildChecked)route();};
